insert into public.case_items (id, code, kind, status, origin, domain_id, difficulty, title, vignette, source_note, version)
insert into public.case_steps (id, case_id, position, info, prompt) values ('88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 1, '{"en":"You are the duty assistant at the fictional Harbour Island ferry office. At 07:00 the printed timetable board is blank and the first passengers are arriving."}'::jsonb, '{"en":"What do you do first?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('539801f6-1126-42de-81e6-45c01ba080de'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 1, '{"en":"Rewrite a timetable from memory and pin it to the board."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('539801f6-1126-42de-81e6-45c01ba080de'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 0, 3, 'independent_nursing', '{"en":"Writing times from memory risks publishing wrong departures. Anything shown to the public should come from the office''s confirmed schedule. This part of the job is yours to do, but only with checked information."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('d5a17559-6ebb-4dd8-873f-e105e192e0ca'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 2, '{"en":"Open the office''s shared schedule to confirm today''s departures, then decide what to tell passengers."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('d5a17559-6ebb-4dd8-873f-e105e192e0ca'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 2, 2, 'assessment', '{"en":"Checking the confirmed source first is the best opening move. It is inside your role, it is quick, and it gives you facts before you act or escalate."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('2577938f-a112-4ea0-8488-7da00575faad'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 3, '{"en":"Tell the harbour manager the board is blank and wait for instructions before doing anything else."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('2577938f-a112-4ea0-8488-7da00575faad'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, '88505227-d657-48e7-8f5f-24d704a2654a'::uuid, 1, 2, 'escalation', '{"en":"Letting the manager know is reasonable, but waiting with nothing done leaves passengers uninformed. A quick check of the confirmed schedule first would let you report with facts."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 2, '{"en":"The shared schedule shows the first ferry at 08:10. A note says engine checks may delay it. A passenger asks when the first ferry leaves."}'::jsonb, '{"en":"What do you tell the passenger?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('4673a929-1037-4147-8d28-1441fe1865c1'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 1, '{"en":"Say it leaves at 08:10 and leave out the note about checks, to avoid worrying anyone."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('4673a929-1037-4147-8d28-1441fe1865c1'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 0, 4, 'independent_nursing', '{"en":"Leaving out a known possible delay misleads the passenger. Being clear about what you know and do not know is part of your role."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('3d5a262c-1e62-40a6-8fb7-4f4ec3441012'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 2, '{"en":"Say you cannot answer and ask the passenger to come back later."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('3d5a262c-1e62-40a6-8fb7-4f4ec3441012'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 1, 4, 'prescriber_or_other_discipline', '{"en":"You do have the information, so passing the question on is unnecessary. Deciding to cancel or retime a ferry belongs to the harbour manager, but sharing the confirmed schedule does not."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('8242dafe-ceb0-46b0-8293-4483f21d58e4'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 3, '{"en":"Say it is due at 08:10 and that a delay is possible, and that you will update the board when you know more."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('8242dafe-ceb0-46b0-8293-4483f21d58e4'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'cc231517-09a6-4523-8719-4b1da11e7a1c'::uuid, 2, 4, 'independent_nursing', '{"en":"Giving the confirmed time together with the known uncertainty is honest and within your role. It also sets up a clear follow-up."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 3, '{"en":"A passenger shows you your handwritten note. The times differ from the website."}'::jsonb, '{"en":"What is the best next step?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('40b7c5f8-820c-42bf-82a0-9020ddeb08f6'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 1, '{"en":"Ask the manager to correct the website to match your note."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('40b7c5f8-820c-42bf-82a0-9020ddeb08f6'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 1, 4, 'prescriber_or_other_discipline', '{"en":"Changing the website is the manager''s or IT''s decision, and here the website was right. Asking is not harmful, but it does not fix the problem."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('ecb851f6-f134-4330-8d9e-603624f9c6dc'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 2, '{"en":"Remove the note, apologise, and replace it with the confirmed schedule."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('ecb851f6-f134-4330-8d9e-603624f9c6dc'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 2, 4, 'independent_nursing', '{"en":"Correcting your own error quickly and openly is within your role and protects other passengers."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('73fadc40-f9da-4ad3-8565-92b5dd945dfc'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 3, '{"en":"Leave the note up and say the website is probably wrong."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('73fadc40-f9da-4ad3-8565-92b5dd945dfc'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'c78cfc7f-515d-4e8f-8375-0e1214b7f070'::uuid, 0, 4, 'independent_nursing', '{"en":"Defending an unchecked note is the opposite of using the confirmed source. The website matched the schedule."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 4, '{"en":"Later the manager asks what happened this morning."}'::jsonb, '{"en":"What do you do?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('36cc296b-d238-4b27-8e42-d385e4447b87'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 1, '{"en":"Give a short, factual account, including the note you wrote and corrected, and suggest keeping a printed backup schedule."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('36cc296b-d238-4b27-8e42-d385e4447b87'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 2, null, 'escalation', '{"en":"A candid report lets the manager fix the cause. Reporting is expected and is not a sign of failure."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('adf9c89f-948b-498e-8d48-9c1ff35c3681'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 2, '{"en":"Say the board was blank when you arrived and leave it there."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('adf9c89f-948b-498e-8d48-9c1ff35c3681'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 1, null, 'escalation', '{"en":"This is true, but leaving out your own part prevents the team from learning."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('713af3d9-7cdd-4005-8ccd-8542252c973f'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 3, '{"en":"Say there was no problem this morning."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('713af3d9-7cdd-4005-8ccd-8542252c973f'::uuid, 'c66107b5-97ee-427a-8364-4f5881d8567a'::uuid, 'dacc48e6-9e6d-4bca-8aff-b8d0e1da558d'::uuid, 0, null, 'escalation', '{"en":"This hides a real event and removes the chance to prevent it happening again."}'::jsonb);
insert into public.case_items (id, code, kind, status, origin, domain_id, difficulty, title, vignette, source_note, version)
insert into public.case_steps (id, case_id, position, info, prompt) values ('4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, 1, '{"en":"You are the duty assistant in the quiet reading room. A group at the back is talking loudly and two readers look annoyed."}'::jsonb, '{"en":"What do you do first?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('bacd8a57-34de-4fde-8829-bd13258a702e'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 1, '{"en":"Switch off the lights in their corner to make them leave."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('bacd8a57-34de-4fde-8829-bd13258a702e'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 0, 3, 'independent_nursing', '{"en":"This is a punishment, not a request, and it could cause a safety problem. It is not part of your role."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('25b112d4-382c-4de7-8ab8-7c63fec7c8ed'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 2, '{"en":"Call the library manager at once to have the group removed."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('25b112d4-382c-4de7-8ab8-7c63fec7c8ed'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 1, 3, 'escalation', '{"en":"Escalating is available to you, but a polite request has not been tried yet, so it is early. Keep escalation for when it is needed."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('32834779-159c-440d-8758-e256dc9ee640'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 3, '{"en":"Ask the group quietly and politely to lower their voices and point out the quiet-room sign."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('32834779-159c-440d-8758-e256dc9ee640'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '4b55a349-e4ae-4076-8512-8a03f3775d0f'::uuid, 2, 2, 'independent_nursing', '{"en":"A courteous request is within your role and often enough. It keeps the room calm and respects everyone."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('1b535520-9338-4965-865d-fcc0474c454f'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, 2, '{"en":"The group quietens for a minute, then becomes loud again."}'::jsonb, '{"en":"What is the best next step?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('00c0a6aa-0736-4e4f-82b0-c70f3cab1dce'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 1, '{"en":"Tell the group they are banned from the library."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('00c0a6aa-0736-4e4f-82b0-c70f3cab1dce'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 0, 3, 'prescriber_or_other_discipline', '{"en":"Banning a visitor is a decision for the library manager under the written conduct procedure, not for you."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('4dab2c5b-3c5f-43d8-8ea0-34635dbbef35'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 2, '{"en":"Explain the room rule again and offer the discussion room next door, which is free."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('4dab2c5b-3c5f-43d8-8ea0-34635dbbef35'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 2, 3, 'independent_nursing', '{"en":"Offering a practical alternative solves the cause and is within your role."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('9fe63875-7203-457d-8e5e-a48305f794e5'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 3, '{"en":"Ignore it, since you already asked once."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('9fe63875-7203-457d-8e5e-a48305f794e5'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '1b535520-9338-4965-865d-fcc0474c454f'::uuid, 0, 3, 'independent_nursing', '{"en":"Leaving a repeated problem stops the room being quiet for others."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, 3, '{"en":"The group refuses to move and becomes rude to you."}'::jsonb, '{"en":"What do you do?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('fb2a0ad7-d9a6-4ce3-8d05-124437ce0a66'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 1, '{"en":"Stay calm, tell them the manager will speak to them, and contact the manager."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('fb2a0ad7-d9a6-4ce3-8d05-124437ce0a66'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 2, null, 'escalation', '{"en":"Handing over to the manager when a request has failed is the right use of escalation."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('61a02b28-3fde-44fe-8215-782aec8b9a2d'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 2, '{"en":"Raise your voice and argue until they agree."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('61a02b28-3fde-44fe-8215-782aec8b9a2d'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 0, null, 'independent_nursing', '{"en":"Arguing makes the noise worse and does not follow a calm approach."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('d3bf7d9b-19af-42c8-8a8d-c7e7d36018bc'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 3, '{"en":"Offer to write down what happened for the manager but take no further action."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('d3bf7d9b-19af-42c8-8a8d-c7e7d36018bc'::uuid, '8f666f66-7099-4b11-8c77-602c35e1d83b'::uuid, '90c18312-dfaf-4ec6-8115-2d0b00305c88'::uuid, 1, null, 'escalation', '{"en":"A written note helps, but the manager also needs to be contacted so the group can be dealt with now."}'::jsonb);
insert into public.case_items (id, code, kind, status, origin, domain_id, difficulty, title, vignette, source_note, version)
insert into public.case_steps (id, case_id, position, info, prompt) values ('04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 1, '{"en":"A reader returns a book that is three weeks overdue. The desk system shows a fine, and the reader says the book was renewed by phone."}'::jsonb, '{"en":"What do you do first?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('9271c949-4f17-485d-84f4-02c1606d244f'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 1, '{"en":"Tell the reader the fine stands and end the conversation."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('9271c949-4f17-485d-84f4-02c1606d244f'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 0, 3, 'independent_nursing', '{"en":"Refusing to look at the record is unhelpful and may be unfair if the renewal really happened."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('1999748b-9ca1-413e-840a-d2e82e738428'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 2, '{"en":"Look at the renewal log in the desk system for that book."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('1999748b-9ca1-413e-840a-d2e82e738428'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 2, 2, 'assessment', '{"en":"Checking the record is the most useful first step. It is inside your role and gives you facts."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('f42e5e43-38e6-4815-8830-b90210374e6e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 3, '{"en":"Cancel the fine because the reader says it was renewed."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('f42e5e43-38e6-4815-8830-b90210374e6e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '04d64e54-70b6-4eff-8368-ebc3cad26b88'::uuid, 1, 3, 'order_or_protocol_required', '{"en":"Cancelling a fine needs the written fine-waiver procedure or the manager''s approval, not just a reader''s word."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 2, '{"en":"The log shows a renewal request on the 3rd, but it was never confirmed."}'::jsonb, '{"en":"What do you do?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('ac193568-9ba2-46c8-811f-c76082f7f069'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 1, '{"en":"Explain what the log shows, then follow the fine-waiver procedure to request a waiver from the manager."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('ac193568-9ba2-46c8-811f-c76082f7f069'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 2, 4, 'order_or_protocol_required', '{"en":"The waiver needs the written procedure, and you can start it. This respects the rule and helps the reader."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('b853b561-1a4b-4cff-845c-4f00aa5a914e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 2, '{"en":"Remove the fine yourself because it looks like a mistake."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('b853b561-1a4b-4cff-845c-4f00aa5a914e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 0, 4, 'order_or_protocol_required', '{"en":"Fines may only be waived through the procedure, even when it looks like an error."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('8f1b17b5-88e9-40ba-8aa5-4cc871de9b7a'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 3, '{"en":"Tell the reader to come back and ask the manager."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('8f1b17b5-88e9-40ba-8aa5-4cc871de9b7a'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, '06632b9d-3ce2-4d32-85e2-1f5cee8723c8'::uuid, 1, 4, 'escalation', '{"en":"Passing it on works, but you could have started the waiver for them."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 3, '{"en":"The reader has no record of any renewal confirmation, and the log shows nothing for that date."}'::jsonb, '{"en":"What do you do?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('553935ed-629c-476d-80eb-7afa35549197'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 1, '{"en":"Accept the fine and say nothing about the unclear record."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('553935ed-629c-476d-80eb-7afa35549197'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 1, 4, 'independent_nursing', '{"en":"The fine may be correct, but ignoring the missing renewal record leaves a possible system error unreported."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('4a85438f-39ac-478d-800a-08ce02f57444'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 2, '{"en":"Tell the reader you will delete the loan record to make it go away."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('4a85438f-39ac-478d-800a-08ce02f57444'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 0, 4, 'prescriber_or_other_discipline', '{"en":"Deleting records is a decision for the manager or IT, and it would remove evidence."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('bff6a048-fcb2-4dda-8c85-b71cf0ee9016'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 3, '{"en":"Explain the record is unclear, offer to note the reader''s account, and ask the manager how to proceed."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('bff6a048-fcb2-4dda-8c85-b71cf0ee9016'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'b4160e28-e4a0-46be-8021-693f64adac8a'::uuid, 2, 4, 'escalation', '{"en":"Writing down the account and escalating handles the uncertainty fairly."}'::jsonb);
insert into public.case_steps (id, case_id, position, info, prompt) values ('df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 4, '{"en":"The manager asks you to finish the paperwork for the case."}'::jsonb, '{"en":"What do you do?"}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('a96b7b73-a14b-4a74-8e7b-d0b49bfa686a'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 1, '{"en":"Leave the paperwork for the next shift."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('a96b7b73-a14b-4a74-8e7b-d0b49bfa686a'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 0, null, 'independent_nursing', '{"en":"Delaying records makes details harder to remember accurately."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('73d05651-4cef-4f76-8f5c-97fa3020101e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 2, '{"en":"Record what the reader said, what the log showed and what was decided, in the desk notes."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('73d05651-4cef-4f76-8f5c-97fa3020101e'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 2, null, 'independent_nursing', '{"en":"Clear, factual notes are part of your role and protect everyone."}'::jsonb);
insert into public.case_step_options (id, case_id, step_id, position, text) values ('a975a4a7-b5a8-462e-8802-9f0386e94b10'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 3, '{"en":"Write only the decision."}'::jsonb);
insert into public.case_option_keys (option_id, case_id, step_id, points, next_position, scope, feedback) values ('a975a4a7-b5a8-462e-8802-9f0386e94b10'::uuid, '91f92385-934d-48e2-8244-50796791cc33'::uuid, 'df8f7618-46fb-4a4b-8ed4-5ffe019ed564'::uuid, 1, null, 'independent_nursing', '{"en":"The decision matters, but without the facts behind it the notes cannot be checked later."}'::jsonb);
